import{_ as e,o as r,c as d,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Keyboard shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/keyboard.md","filePath":"guide/keyboard.md","lastUpdated":1793532752000}'),a={name:"guide/keyboard.md"};function h(i,t,n,l,s,c){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>json-tool can be used without a mouse. Every control can be reached with <strong>Tab</strong> and activated with <strong>Enter</strong> or <strong>Space</strong>, and each action also has a dedicated shortcut so you do not have to tab through the page.</p><p>Press <strong>?</strong> (when you are not typing in an editor) to open the shortcut list inside the app. The list only shows the shortcuts available on the current page.</p><h2 id="navigation-and-views" tabindex="-1">Navigation and views <a class="header-anchor" href="#navigation-and-views" aria-label="Permalink to &quot;Navigation and views&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td>Alt + 1 or Alt + Home</td><td>Go to the home view</td></tr><tr><td>Alt + 2</td><td>Go to the table view</td></tr><tr><td>Alt + 3</td><td>Go to the shape view</td></tr><tr><td>Alt + 4</td><td>Go to the diff view</td></tr><tr><td>Alt + 5 or Alt + S</td><td>Go to the settings view</td></tr><tr><td>Alt + H</td><td>Open or close the history drawer (when JSON History is enabled)</td></tr><tr><td>Alt + D or Alt + Shift + D</td><td>Open the documentation in a new tab</td></tr></tbody></table><h2 id="header" tabindex="-1">Header <a class="header-anchor" href="#header" aria-label="Permalink to &quot;Header&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td>Alt + J</td><td>Toggle <strong>validate json</strong></td></tr><tr><td>Alt + Y</td><td>Toggle <strong>sync scroll</strong></td></tr><tr><td>Alt + M</td><td>Toggle dark mode</td></tr></tbody></table><h2 id="editors" tabindex="-1">Editors <a class="header-anchor" href="#editors" aria-label="Permalink to &quot;Editors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td>Alt + Shift + W</td><td>Focus the working editor (left)</td></tr><tr><td>Alt + Shift + R</td><td>Focus the result or compare editor (right)</td></tr><tr><td>Tab</td><td>Move to the next control, including out of the JSON editors</td></tr><tr><td>Shift + Tab</td><td>Move to the previous control</td></tr><tr><td>Ctrl/⌘ + F</td><td>Search in the working editor</td></tr><tr><td>Ctrl/⌘ + Shift + F</td><td>Search in the result editor</td></tr></tbody></table><p>The editors do not capture <strong>Tab</strong>, so you can always leave an editor and reach its toolbar, the divider, the other editor, the header and the footer.</p><p>The <strong>Alt + Shift + W</strong> and <strong>Alt + Shift + R</strong> shortcuts jump directly into the left and right editors, so you can start typing without using the mouse or tabbing through the page.</p><h2 id="working-editor-left" tabindex="-1">Working editor (left) <a class="header-anchor" href="#working-editor-left" aria-label="Permalink to &quot;Working editor (left)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td>Ctrl/⌘ + F</td><td>Search in the working editor</td></tr><tr><td>Alt + V</td><td>Paste from the clipboard</td></tr><tr><td>Alt + O</td><td>Upload a JSON file</td></tr><tr><td>Alt + Delete</td><td>Delete all</td></tr></tbody></table><h2 id="result-editor-right-home-view" tabindex="-1">Result editor (right, home view) <a class="header-anchor" href="#result-editor-right-home-view" aria-label="Permalink to &quot;Result editor (right, home view)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td>Ctrl/⌘ + Shift + F</td><td>Search in the result editor</td></tr><tr><td>Alt + Shift + T</td><td>Focus the space tabulation input</td></tr><tr><td>Alt + Shift + S</td><td>Clean spaces</td></tr><tr><td>Alt + Shift + N</td><td>Clean new lines</td></tr><tr><td>Alt + Shift + B</td><td>Clean new lines and spaces</td></tr><tr><td>Alt + Shift + C</td><td>Copy the result</td></tr></tbody></table><h2 id="table-view" tabindex="-1">Table view <a class="header-anchor" href="#table-view" aria-label="Permalink to &quot;Table view&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td>Alt + G</td><td>Focus the table search</td></tr><tr><td>Alt + E</td><td>Toggle <strong>Exact match</strong></td></tr><tr><td>Alt + Enter</td><td>Toggle full screen</td></tr></tbody></table><h2 id="shape-view" tabindex="-1">Shape view <a class="header-anchor" href="#shape-view" aria-label="Permalink to &quot;Shape view&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td>Alt + E</td><td>Expand all nested shapes</td></tr><tr><td>Alt + W</td><td>Collapse all nested shapes</td></tr></tbody></table><h2 id="settings-view" tabindex="-1">Settings view <a class="header-anchor" href="#settings-view" aria-label="Permalink to &quot;Settings view&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td>Alt + Enter</td><td>Save the settings</td></tr></tbody></table><h2 id="diff-view" tabindex="-1">Diff view <a class="header-anchor" href="#diff-view" aria-label="Permalink to &quot;Diff view&quot;">​</a></h2><p>The original editor uses the <a href="#working-editor-left">working editor</a> shortcuts. The compare editor uses:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td>Ctrl/⌘ + Shift + F</td><td>Search in the compare editor</td></tr><tr><td>Alt + Shift + V</td><td>Paste from the clipboard</td></tr><tr><td>Alt + Shift + O</td><td>Upload a JSON file</td></tr><tr><td>Alt + Shift + Delete</td><td>Delete all</td></tr></tbody></table><h2 id="dialogs-and-full-screen" tabindex="-1">Dialogs and full screen <a class="header-anchor" href="#dialogs-and-full-screen" aria-label="Permalink to &quot;Dialogs and full screen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td>?</td><td>Open or close the shortcut list</td></tr><tr><td>Esc</td><td>Close the shortcut list or the history drawer, or exit the table full screen</td></tr></tbody></table><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td>Tab</td><td>Move to the next control, including out of the JSON editors</td></tr><tr><td>Shift + Tab</td><td>Move to the previous control</td></tr><tr><td>Enter or Space</td><td>Activate the focused button, link or checkbox</td></tr><tr><td>Left / Right arrow</td><td>Resize the editors when the divider between them is focused</td></tr><tr><td>Home / End</td><td>Use the minimum or maximum editor width when the divider is focused</td></tr></tbody></table><p>The editors do not capture <strong>Tab</strong>, so you can always leave an editor and reach its toolbar, the divider, the other editor, the header and the footer.</p><p>The focused control is highlighted with a yellow outline. The history drawer keeps the focus inside it while it is open, and returns the focus to the history button when it is closed.</p><h2 id="editors-1" tabindex="-1">Editors <a class="header-anchor" href="#editors-1" aria-label="Permalink to &quot;Editors&quot;">​</a></h2><p>The editors support the usual editing keys, including undo/redo and the CodeMirror search panel. Press <strong>Esc</strong> to close the search panel.</p>',32)])])}const g=e(a,[["render",h]]);export{u as __pageData,g as default};
